namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour
2 eggs
1 cup milk
2 tbsp sugar
1 tsp baking powder", Steps = "1. Mix dry ingredients
2. Whisk eggs and milk together
3. Combine wet and dry ingredients
4. Cook on griddle until golden", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Avocado Toast", Category = "Breakfast", Ingredients = "2 slices sourdough bread
1 ripe avocado
Salt and pepper
Red pepper flakes
Lemon juice", Steps = "1. Toast bread until golden
2. Mash avocado with lemon juice
3. Spread on toast
4. Season with salt, pepper, and red pepper flakes", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 3, Title = "Grilled Chicken Salad", Category = "Lunch", Ingredients = "2 chicken breasts
Mixed greens
Cherry tomatoes
Cucumber
Olive oil vinaigrette", Steps = "1. Season and grill chicken breasts
2. Slice chicken
3. Toss greens with tomatoes and cucumber
4. Top with chicken and drizzle dressing", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Tomato Soup", Category = "Lunch", Ingredients = "6 large tomatoes
1 onion
3 cloves garlic
Vegetable broth
Fresh basil
Heavy cream", Steps = "1. Roast tomatoes, onion, and garlic
2. Blend with broth until smooth
3. Simmer for 20 minutes
4. Stir in cream and fresh basil", AverageRating = 4.3, RatingCount = 10 },
        new Recipe { Id = 5, Title = "Spaghetti Carbonara", Category = "Dinner", Ingredients = "400g spaghetti
200g pancetta
4 egg yolks
100g Pecorino Romano
Black pepper", Steps = "1. Cook pasta al dente
2. Fry pancetta until crispy
3. Mix egg yolks with cheese
4. Toss hot pasta with pancetta then egg mixture
5. Season with black pepper", AverageRating = 4.8, RatingCount = 22 },
        new Recipe { Id = 6, Title = "Beef Stir Fry", Category = "Dinner", Ingredients = "500g beef sirloin
Bell peppers
Broccoli
Soy sauce
Ginger
Garlic
Sesame oil", Steps = "1. Slice beef thinly
2. Heat wok with sesame oil
3. Stir fry beef until browned
4. Add vegetables and sauce
5. Cook until veggies are tender-crisp", AverageRating = 4.4, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Chocolate Brownies", Category = "Desserts", Ingredients = "200g dark chocolate
150g butter
3 eggs
200g sugar
100g flour
Pinch of salt", Steps = "1. Melt chocolate and butter together
2. Whisk eggs and sugar
3. Fold in chocolate mixture
4. Add flour and salt
5. Bake at 180°C for 25 minutes", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 8, Title = "Lemon Tart", Category = "Desserts", Ingredients = "Shortcrust pastry
4 lemons (juice and zest)
4 eggs
200g sugar
200ml double cream", Steps = "1. Blind bake pastry shell
2. Whisk eggs, sugar, lemon juice and zest
3. Stir in cream
4. Pour into shell and bake at 150°C for 30 minutes", AverageRating = 4.6, RatingCount = 14 },
    };

    private int _nextId = 9;

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
        }
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

