arguments.file_text:
@page "/recipes/{Category}"
@inject RecipeCommunity.Services.RecipeService RecipeService

<PageTitle>@Category Recipes</PageTitle>

<h1>@Category Recipes</h1>
<p><a href="/">← Back to categories</a></p>

@if (recipes.Any())
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <div class="recipe-card">
                <a href="/recipe/@recipe.Id">
                    <h3>@recipe.Title</h3>
                    <div class="recipe-meta">
                        @if (recipe.RatingCount > 0)
                        {
                            <span class="stars">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                            <span class="rating-info">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
                        }
                        else
                        {
                            <span class="no-ratings">No ratings yet</span>
                        }
                    </div>
                </a>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<style>
    .recipe-list { display: flex; flex-direction: column; gap: 1rem; max-width: 600px; }
    .recipe-card {
        border: 1px solid #e0e0e0;
        border-radius: 8px;
        padding: 1rem 1.5rem;
        transition: box-shadow 0.2s;
    }
    .recipe-card:hover { box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
    .recipe-card a { text-decoration: none; color: inherit; }
    .recipe-card h3 { margin: 0 0 0.5rem 0; }
    .recipe-meta { color: #666; font-size: 0.9rem; }
    .stars { color: #f5a623; margin-right: 0.5rem; }
    .no-ratings { font-style: italic; }
</style>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    private List<RecipeCommunity.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeCommunity.Services.RecipeService RecipeService

@if (recipe is not null)
{
    <PageTitle>@recipe.Title</PageTitle>

    <p><a href="/recipes/@recipe.Category.ToLower()">← Back to @recipe.Category</a></p>

    <h1>@recipe.Title</h1>
    <span class="badge">@recipe.Category</span>

    @if (recipe.RatingCount > 0)
    {
        <p class="avg-rating">
            <span class="stars">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
            @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
        </p>
    }

    <h2>Ingredients</h2>
    <ul class="ingredients">
        @foreach (var line in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@line</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol class="steps">
        @foreach (var line in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = System.Text.RegularExpressions.Regex.Replace(line, @"^\d+\.\s*", "");
            <li>@text</li>
        }
    </ol>

    <RecipeCommunity.Components.Shared.StarRating RecipeId="recipe.Id" />
}
else
{
    <PageTitle>Recipe Not Found</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe. <a href="/">Browse categories</a></p>
}

<style>
    .badge {
        display: inline-block;
        background: #e8f5e9;
        color: #2e7d32;
        padding: 0.25rem 0.75rem;
        border-radius: 20px;
        font-size: 0.85rem;
        font-weight: 500;
    }
    .avg-rating { font-size: 1.1rem; margin: 1rem 0; }
    .stars { color: #f5a623; }
    .ingredients li { margin-bottom: 0.25rem; }
    .steps li { margin-bottom: 0.5rem; line-height: 1.5; }
</style>

@code {
    [Parameter] public int Id { get; set; }
    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeCommunity.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="success-message">
        <h3>✅ Recipe Submitted!</h3>
        <p>Thank you for sharing "<strong>@_model.Title</strong>" with the community.</p>
        <p><a href="/">Browse recipes</a> | <button class="btn-link" @onclick="Reset">Submit another</button></p>
    </div>
}
else
{
    <form @onsubmit="HandleSubmit" class="recipe-form">
        <div class="form-group">
            <label for="title">Recipe Title</label>
            <input id="title" @bind="_model.Title" required placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <select id="category" @bind="_model.Category" required>
                <option value="">Select a category...</option>
                <option value="Breakfast">Breakfast</option>
                <option value="Lunch">Lunch</option>
                <option value="Dinner">Dinner</option>
                <option value="Desserts">Desserts</option>
            </select>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <textarea id="ingredients" @bind="_model.Ingredients" rows="6" required
                      placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs"></textarea>
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <textarea id="steps" @bind="_model.Steps" rows="6" required
                      placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients"></textarea>
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </form>
}

<style>
    .recipe-form { max-width: 600px; }
    .form-group { margin-bottom: 1.25rem; }
    .form-group label { display: block; font-weight: 600; margin-bottom: 0.4rem; }
    .form-group input, .form-group select, .form-group textarea {
        width: 100%;
        padding: 0.6rem;
        border: 1px solid #ccc;
        border-radius: 6px;
        font-size: 1rem;
    }
    .btn-submit {
        background: #2e7d32;
        color: white;
        border: none;
        padding: 0.75rem 2rem;
        border-radius: 6px;
        font-size: 1rem;
        cursor: pointer;
    }
    .btn-submit:hover { background: #1b5e20; }
    .btn-link {
        background: none;
        border: none;
        color: #1a6bc4;
        cursor: pointer;
        text-decoration: underline;
        font-size: inherit;
    }
    .success-message {
        background: #e8f5e9;
        border: 1px solid #a5d6a7;
        border-radius: 8px;
        padding: 1.5rem;
        max-width: 500px;
    }
</style>

@code {
    private RecipeCommunity.Models.RecipeSubmission _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(_model.Title) &&
            !string.IsNullOrWhiteSpace(_model.Category) &&
            !string.IsNullOrWhiteSpace(_model.Ingredients) &&
            !string.IsNullOrWhiteSpace(_model.Steps))
        {
            RecipeService.SubmitRecipe(_model);
            _submitted = true;
        }
    }

    private void Reset()
    {
        _model = new();
        _submitted = false;
    }
}

